SET NOCOUNT ON;
IF DB_NAME()<>N'FinanceLogistics_Dev' THROW 51000,'Select FinanceLogistics_Dev.',1;
SELECT s.SourceCode,s.IsActive,ss.ScopeCode,sp.SiteCode FROM cfg.SourceType s LEFT JOIN cfg.SourceScope ss ON ss.SourceCode=s.SourceCode LEFT JOIN cfg.ScopeSite sp ON sp.ScopeCode=ss.ScopeCode WHERE s.OwnerRoleCode='LOGISTICS' ORDER BY s.SourceCode;
SELECT t.SourceCode,t.TemplateVersionId,t.VersionNo,t.Status,JSON_VALUE(t.DefinitionJson,'$.profile') Profile,JSON_VALUE(t.DefinitionJson,'$.sheet') Sheet FROM cfg.TemplateVersion t JOIN cfg.SourceType s ON s.SourceCode=t.SourceCode WHERE s.OwnerRoleCode='LOGISTICS' ORDER BY t.SourceCode,t.VersionNo;
SELECT r.SourceCode,r.RequirementId,r.ScopeCode,p.PeriodCode,p.Status PeriodStatus,r.ActiveBatchId,p.DataRevision,CONVERT(varchar(18),r.RowVersion,1) RequirementRowVersion,JSON_VALUE(r.PolicySnapshotJson,'$.logisticsPeriodMode') PeriodMode,JSON_VALUE(r.PolicySnapshotJson,'$.coverageStart') CoverageStart,JSON_VALUE(r.PolicySnapshotJson,'$.coverageEndExclusive') CoverageEndExclusive FROM ingest.SubmissionRequirement r JOIN cfg.ReportingPeriod p ON p.PeriodId=r.PeriodId JOIN cfg.SourceType s ON s.SourceCode=r.SourceCode WHERE s.OwnerRoleCode='LOGISTICS' ORDER BY p.PeriodCode,r.SourceCode;
